 async function applyAndPreview(c:Pause,s:number,e:number){try{const prior=pRef.current,next=commitBounds(c,s,e);if(!next)return;setDraft(c.id,null);await batch(3,false,c.id,next,next.revision!==prior?.revision,next.revision===prior?.revision||view!=='source')}catch(e){fail(e);throw e}}
 async function extendSelected(){const before=pRef.current,cut=plan?.removed.find(c=>before?.pauses.some(x=>x.id===selected&&x.startUs>=c.startUs&&x.endUs<=c.endUs));if(!before||!cut)return;const result=await run<Preview>('preview',{project:before,positionUs:cut.outputUs,halfSeconds:6});if(!mediaRevisions.accepts(before))return;const existing=entries.find(e=>e.cutUs===cut.outputUs);if(existing){const extended={...existing,...result,id:existing.id,status:'ready' as const};setEntries(old=>old.map(e=>e.id===existing.id?extended:e));loadEntry(extended,extended.startUs,false)}else{setPreview(result);setActiveEntry(null);setView('result');issuePlayback('full',result.startUs,false,'延长此处预览')}}
 async function thumbnails(c:Pause){const before=pRef.current;if(!before)return;const paths=[];for(const us of[c.startUs,Math.min(c.endUs,before.source.framePts.at(-1)!)])paths.push((await run<{path:string}>('thumbnail',{project:before,timeUs:us})).path);if(mediaRevisions.accepts(before))setThumbs(paths)}
 async function selectVideo(index:number){if(!pRef.current||index===pRef.current.videoIndex)return;if(await choose('切换视频流将重新建立帧索引并清空旧区间。',['切换','返回'])!==0)return;const next=await run<Project>('selectVideo',{project:pRef.current,index});apply(next,'切换视频流');setSourceProxy('');setEntries([])}
 async function showSettings(){media.pauseAll();const v=await api<{cacheBytes:number;settings:{cacheLimit:number}}>('settings');setCacheGB(v.settings.cacheLimit/1024**3);setCacheBytes(v.cacheBytes);setSettingsOpen(true)}
 useEffect(()=>{const isSpace=(e:KeyboardEvent)=>e.code==='Space'||e.key===' '||e.key==='Spacebar',consume=(e:KeyboardEvent)=>{e.preventDefault();e.stopImmediatePropagation()},listener=(e:KeyboardEvent)=>{const el=e.target as HTMLElement,typing=el instanceof HTMLElement&&(el.matches('input:not([type=range]):not([type=checkbox]):not([type=button]),textarea')||el.isContentEditable);
  if(isSpace(e)){if(e.type==='keyup'){if(spaceOwned.current)consume(e);spaceOwned.current=false;spaceHeld.current=false;return}if(e.ctrlKey||e.metaKey||e.altKey)return;if(spaceHeld.current||e.repeat){if(spaceOwned.current)consume(e);return}if(media.isPlaying()||!typing&&!e.isComposing){spaceHeld.current=true;spaceOwned.current=true;consume(e);media.toggle()}return}
  if(e.type==='keyup'||e.defaultPrevented||e.isComposing||modalRef.current||choosing)return;
  const textControl=typing||el instanceof HTMLSelectElement;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='o'){e.preventDefault();act(()=>openProject())}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();act(()=>writer.flush())}if(!textControl&&(e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();if(!e.repeat)restore(e.shiftKey?'redo':'undo')}if(!textControl&&!disabled&&view==='source'){if(e.key==='[')setMark(current);if(e.key===']'&&mark!==null)addPause(mark,current)}};
  const clear=()=>{spaceHeld.current=false;spaceOwned.current=false};window.addEventListener('keydown',listener,true);window.addEventListener('keyup',listener,true);window.addEventListener('blur',clear);return()=>{window.removeEventListener('keydown',listener,true);window.removeEventListener('keyup',listener,true);window.removeEventListener('blur',clear)}});
 useEffect(()=>{const close=(e:MouseEvent)=>{document.querySelectorAll<HTMLDetailsElement>('.menu[open],.more[open],.info-pop[open]').forEach(el=>{if(!el.contains(e.target as Node))el.open=false})};const escape=(e:KeyboardEvent)=>{if(e.key!=='Escape'||document.querySelector('[role=dialog]'))return;const open=[...document.querySelectorAll<HTMLDetailsElement>('.menu[open],.info-pop[open]')];if(!open.length)return;e.preventDefault();e.stopImmediatePropagation();open.forEach(el=>el.open=false);open[0].querySelector<HTMLElement>('summary')?.focus({preventScroll:true})};window.addEventListener('click',close);window.addEventListener('keydown',escape,true);return()=>{window.removeEventListener('click',close);window.removeEventListener('keydown',escape,true)}},[]);
