 const name=p?.name|| (p?fileName(p.source.fingerprint.path).replace(/\.[^.]+$/,''):'新项目'),saveLabel=saveState==='failed'?'保存失败':saveState==='pending'||saveState==='saving'?'正在保存…':'已自动保存';
